const cfg = $('Load config').first().json;
const model = (cfg.models && cfg.models.analysis) || 'gpt-5-mini';
const maxChars = (cfg.pipeline && cfg.pipeline.max_content_chars) || 24000;
const items = $input.all().map((i) => i.json).filter((x) => x && x.id);
